using System;using System.IO;using System.Collections;using System.Linq;using UnityEngine;using UnityEditor;using Unity.XR.CoreUtils;using UnityEngine.Rendering;using LighthouseKeepers.WatchDemo;using LighthouseKeepers.Core.Progression;
public class CeilingLightProbe:MonoBehaviour{
 string folder;WatchDemoController w;XROrigin rig;Transform head,child;Camera cam;WatchLantern flash;int failures;RenderPipelineAsset previous;float closest=100;
 public static object Begin(string folder){EditorUtility.audioMasterMute=true;Directory.CreateDirectory(folder);var p=new GameObject("Ceiling movement review").AddComponent<CeilingLightProbe>();p.folder=folder;p.StartCoroutine(p.Go());return true;}
 void Check(bool ok,string text){File.AppendAllText(folder+"/checks.txt",(ok?"PASS ":"FAIL ")+text+"\n");if(!ok)failures++;}
 void Capture(string name){cam.transform.SetPositionAndRotation(head.position,head.rotation);var rt=new RenderTexture(1100,850,24);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1100,850,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1100,850),0,0);tex.Apply();File.WriteAllBytes(folder+"/"+name+".png",tex.EncodeToPNG());RenderTexture.active=null;cam.targetTexture=null;Destroy(tex);Destroy(rt);}
 void Update(){if(!head||!child||!flash)return;var target=child.TransformPoint(Vector3.up*.65f);head.LookAt(target);var p=head.position+head.right*.15f-head.up*.22f;flash.transform.SetPositionAndRotation(p,Quaternion.LookRotation(target-p));var r=child.GetComponent<Renderer>();if(r.enabled)closest=Mathf.Min(closest,Vector3.Distance(head.position,r.bounds.ClosestPoint(head.position)));}
 IEnumerator Go(){w=FindAnyObjectByType<WatchDemoController>();var scene=w.GetComponent<NightmareScene>();rig=FindAnyObjectByType<XROrigin>();head=rig.Camera.transform;foreach(var b in rig.GetComponentsInChildren<Behaviour>(true))if(b.GetType().Name.Contains("TrackedPose")||b.GetType().Name.Contains("InputModality"))b.enabled=false;var cc=rig.GetComponent<CharacterController>();if(cc)cc.enabled=false;HorrorTuning.Current.nightmareEnabled=true;Check(scene.Begin(true),"Nightmare starts");scene.enabled=false;var c=w.State.Scare;for(int i=0;i<200&&c.Beat!=ScareBeat.Turn;i++)c.Tick(.1f,true,true,0,0);c.Place(HorrorTuning.Current.nightmareCorner,0);rig.MoveCameraToWorldLocation(new Vector3(-.4f,4.95f,-.6f));Physics.SyncTransforms();flash=FindObjectsByType<WatchLantern>(FindObjectsSortMode.None).First(x=>x.Slot==0);w.State.CycleLantern(0);scene.enabled=true;yield return null;child=GameObject.Find("Nightmare child").transform;cam=new GameObject("Ceiling review camera").AddComponent<Camera>();cam.enabled=false;cam.fieldOfView=65;cam.nearClipPlane=.04f;previous=QualitySettings.renderPipeline;QualitySettings.renderPipeline=AssetDatabase.LoadAssetAtPath<RenderPipelineAsset>("Assets/_LighthouseKeepers/Settings/RenderPipeline/QuestPipeline.asset");
 while(c.Beat==ScareBeat.Turn&&c.Age<.8f)yield return null;Capture("turn");while(c.Beat==ScareBeat.Turn&&c.Age<2.4f)yield return null;Capture("wall");while(c.Beat==ScareBeat.Turn&&c.Age<3.6f)yield return null;Capture("ceiling");Check(c.Beat==ScareBeat.Turn,"Ceiling pose appears during turn");Check(closest>=.5f,"Visible body stays at least .5 m from viewer ("+closest.ToString("F2")+" m)");Check(ShaderUtil.GetShaderMessages(Shader.Find("Lighthouse/S5 Drowned oilskin")).All(x=>x.severity.ToString()!="Error"),"Quest-pipeline Editor shader has no compilation errors");QualitySettings.renderPipeline=previous;File.WriteAllText(folder+"/result.json","{\"passed\":"+(failures==0?"true":"false")+",\"failures\":"+failures+"}");Destroy(cam.gameObject);Destroy(gameObject);}
}
